block:
{
  // Éditeur complet : session invitée + note 'demo' + bannière fermée.
  'editor': {
    url: b => b + '/n/demo',
    setup: readyEditor,
  },
  // Menu déroulant « More options » (dropdown-toggle Bootstrap).
  'editor-menu': {
    url: b => b + '/n/demo',
    setup: async page => {
      await readyEditor(page);
      await page.locator('button.dropdown-toggle[aria-label="More options"]').first().click();
      await page.waitForSelector('.dropdown-menu.show', { state: 'visible', timeout: 15000 });
      await page.waitForTimeout(600); // fin de la transition
    },
  },
  // Panneau latéral « Note info » (slide-sidebar).
  'editor-sidebar': {
    url: b => b + '/n/demo',
    setup: async page => {
      await readyEditor(page);
      await page.locator('button[class*="sidebar-button"]', { hasText: 'Note info' }).first().click();
      await page.waitForSelector('[class*="sidebar-menu_show"]', { state: 'visible', timeout: 15000 });
      await page.waitForTimeout(600);
    },
  },
}
